window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3badaa1e7ed83a48"]={"versions": [{"id": "FIG-3badaa1e7ed83a48", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML Class Diagram), AUTOSAR Adaptive Platform (TPS Manifest Specification, R23-11, Kapitel 15 <em>Package Management</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Vererbungshierarchie für <code>UploadableDesignElement</code>. Es spezifiziert sämtliche modellbasierten Konfigurations- und Design-Artefakte (ARXML), die über das AUTOSAR Adaptive <em>Update and Configuration Management</em> (UCM) als eigenständige Software Packages bzw. Deployable Content auf eine Zielmaschine übertragen, aktualisiert oder gepatcht werden können, ohne die gesamte Systemkonfiguration neu flashen zu müssen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basis-Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadablePackageElement</code></strong> (<code>ARElement</code>, abstrakt): Wurzelklasse für alle paketierbaren Manifest- und Design-Entitäten innerhalb eines Software Packages.</li>\n<li><strong><code>UploadableDesignElement</code></strong> (abstrakt): Direkte Spezialisierung (<code>Generalization</code>) von <code>UploadablePackageElement</code>. Dient als polymorpher Ankerpunkt für alle Entwurfselemente der System-, Netzwerk-, Sicherheits- und Servicearchitektur.</li>\n</ul>\n<p class=\"fig-p\">#### Abgeleitete Spezialisierungen (Subklassen von <code>UploadableDesignElement</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Service-Oriented Communication & Deployment (ara::com / Middleware):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ServiceInterfaceDeployment</code>: Protokollspezifische Bindung von Schnittstellen (SOME/IP, DDS, IPC).</li>\n<li><code>ServiceInstanceToPortPrototypeMapping</code>: Zuordnung von Service-Instanzen zu Port-Prototypen einer Softwarekomponente.</li>\n<li><code>ServiceInstanceToMachineMapping</code>: Bindung einer Service-Instanz an eine konkrete Maschine (Netzwerk-Endpunkt).</li>\n<li><code>ServiceInstanceToSignalMapping</code> & <code>SignalServiceTranslationPropsSet</code> (<code>ARElement</code>): Gateway-Mapping zwischen klassischer signalbasierter Kommunikation (CAN/LIN/FlexRay) und serviceorientierten Events/Methoden.</li>\n<li><strong>SOME/IP-Spezifika:</strong></li>\n<li><code>SomeipRemoteUnicastConfig</code>, <code>SomeipRemoteMulticastConfig</code> (<code>ARElement</code>).</li>\n<li><code>SomeipSdClientServiceInstanceConfig</code>, <code>SomeipSdServerServiceInstanceConfig</code> (<code>ARElement</code>): SD-Timing und Instanzkonfiguration.</li>\n<li><code>SomeipSdClientEventGroupTimingConfig</code>, <code>SomeipSdServerEventGroupTimingConfig</code> (<code>ARElement</code>).</li>\n<li><code>SomeipDataPrototypeTransformationProps</code>, <code>TransformationPropsSet</code>, <code>TransformationPropsToServiceInterfaceElementMapping</code>, <code>TlvDataIdDefinitionSet</code> (<code>ARElement</code>): Serialisierungs- und TLV-Encoding-Regeln.</li>\n<li><strong>DDS-Spezifika:</strong> <code>DdsSecureGovernance</code>, <code>DdsTopicAccessRule</code> (Zugriffs- und Sicherheitsrichtlinien für DDS-Topics).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk-, Bus- & Protokoll-Stack (FIBEX / Classic & Adaptive Interop):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CommunicationCluster</code> (<code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>): Repräsentation von Bus-Clustern (Ethernet, CAN, CAN XL) mit Unterstützung für Variantenbildung.</li>\n<li><code>CanXlProps</code> (<code>ARElement</code>): Spezifische Frame- und Bitraten-Parameter für CAN XL.</li>\n<li><code>Pdu</code>, <code>ISignal</code>, <code>ISignalGroup</code> (<code>FibexElement</code>): Signal- und PDU-Definitionen für deterministische Buskommunikation.</li>\n<li><code>SocketConnectionIpduIdentifierSet</code> (<code>FibexElement</code>): PDU-zu-Socket-Multiplexing über TCP/UDP.</li>\n<li><code>EthIpProps</code>, <code>EthTcpIpProps</code>, <code>EthTcpIpIcmpProps</code> (<code>ARElement</code>): Parameter für IP/TCP/UDP/ICMP-Stacks (Subnetzmasken, MTU, Window Sizes).</li>\n<li><code>NmConfig</code> (<code>FibexElement</code>): Network Management-Konfiguration (AUTOSAR NM / UDP NM).</li>\n<li><code>GlobalTimeDomain</code> (<code>FibexElement</code>): Synchronisationsdomäne für gPTP / IEEE 802.1AS (ara::tsync).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security, Krypto & Intrusion Detection (ara::crypto, IDS, Firewall):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CryptoServicePrimitive</code>, <code>CryptoServiceKey</code>, <code>CryptoServiceCertificate</code> (<code>ARElement</code>): Konfiguration kryptografischer Algorithmen, Schlüsselzertifikate und Key-Slots.</li>\n<li><code>SecureComProps</code>, <code>IPSecConfigProps</code> (<code>ARElement</code>): Konfiguration gesicherter IP-Verbindungen.</li>\n<li><code>MacSecParticipantSet</code>, <code>MacSecGlobalKayProps</code> [sic: Modell-Typo für <em>Key</em>] (<code>ARElement</code>): Link-Layer-Verschlüsselung nach IEEE 802.1AE.</li>\n<li><code>FirewallRule</code>, <code>StateDependentFirewall</code>: Paketfilter- und Routing-Regeln, abhängig vom Fahrzeug-/Systemzustand.</li>\n<li><code>IdsCommonElement</code>, <code>IdsDesign</code> (<code>ARElement</code>), <code>SecurityEventReportToSecurityEventDefinitionMapping</code>: On-board Intrusion Detection System (IDS / IdsM) Architekturelemente und Security-Event-Filter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Safety, Logging, Tracing & Diagnostik (ara::diag, ara::log):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>E2EProfileConfigurationSet</code>, <code>E2EProfileCompatibilityProps</code> (<code>ARElement</code>): End-to-End-Datenschutzprofile (Data ID, CRC-Offset, Window Size).</li>\n<li><code>DltEcu</code>, <code>DltContext</code>, <code>LogAndTraceMessageCollectionSet</code> (<code>ARElement</code>): DLT-Logging-Kontexte und Filterkataloge.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Topologie, Ausführungseinheiten & Zustandsverwaltung (ara::exec):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>System</code> (<code>ARElement</code>, <code>AtpStructureElement</code>): Gesamtsystemdefinition.</li>\n<li><code>MachineDesign</code> (<code>AtpStructureElement</code>, <code>FibexElement</code>): Hardware- und Netzwerktopologie einer Maschine vor der Software-Allokation.</li>\n<li><code>Executable</code> (<code>AtpClassifier</code>): Definition des ausführbaren Binaries (ELF), das später zu einem <code>Process</code> instantiiert wird.</li>\n<li><code>FunctionGroupSet</code> (<code>AtpClassifier</code>): Zusammenfassung logischer Funktionsgruppen für State Management.</li>\n<li><code>ModeDeclarationGroup</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Modus- und Zustandsraum-Definitionen.</li>\n<li><code>Documentation</code> (<code>ARElement</code>): Modellierte Entwurfsspezifikation/Dokumentation.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches AUTOSAR-Metamodell existiert kein direkter Call-Stack oder sequenzielles Laufzeitverhalten. Die dynamische Relevanz greift im <strong>UCM-Lifecycle</strong>:</p>\n<ol class=\"fig-list\">\n<li><strong>Paket-Ingestion:</strong> UCM (<code>ara::ucm</code>) empfängt ein Software Package (<code>SwPackage</code>), dessen Manifest auf <code>UploadablePackageElement</code> verweist.</li>\n<li><strong>Metamodell-Auflösung:</strong> Der Manifest-Parser validiert die Subklassen von <code>UploadableDesignElement</code> gegen die Schemata der Plattform.</li>\n<li><strong>Inkrementelle Rekonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Werden z. B. <code>FirewallRule</code> oder <code>StateDependentFirewall</code> aktualisiert, triggert der UCM-Aktivierungsschritt eine Neugenerierung bzw. Neuladung der OS-/Kernel-Netfilter-Tabellen.</li>\n<li>Wird ein <code>ServiceInstanceToMachineMapping</code> aktualisiert, rekonfiguriert der ara::com Service-Discovery-Daemon (SOME/IP SD / DDS Discovery) die lokalen Endpunkte zur Laufzeit.</li>\n<li>Änderungen an <code>ModeDeclarationGroup</code> oder <code>FunctionGroupSet</code> synchronisieren die Zustandsübergänge im Execution Management (<code>ara::exec</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>UCM-Granularität & Entkopplung:</strong> Entwickler von Adaptive-Anwendungen müssen Design-Artefakte strikt modular modellieren. Da alle dargestellten Klassen eigenständige <code>UploadableDesignElement</code>-Objekte sind, können Netzwerkmatrizen (FIBEX/Signals), Diagnosekonfigurationen (DLT) und Sicherheitsrichtlinien getrennt von den eigentlichen Executables aktualisiert werden.</li>\n<li><strong>Manifest-Generierung:</strong> Toolchains (Generatoren) kompilieren diese M2-Elemente in spezifische Manifeste:</li>\n<li><code>Executable</code>, <code>FunctionGroupSet</code> $\\rightarrow$ <em>Execution Manifest</em> (<code>.arxml</code> / JSON / BSON).</li>\n<li><code>ServiceInterfaceDeployment</code>, <code>ServiceInstanceToPortPrototypeMapping</code> $\\rightarrow$ <em>Service Instance Manifest</em>.</li>\n<li><code>MachineDesign</code>, <code>EthTcpIpProps</code>, <code>CryptoService<em></code> $\\rightarrow$ </em>Machine Manifest*.</li>\n<li><strong>Variantenmanagement:</strong> Da <code>CommunicationCluster</code> das Stereotyp <code>«atpVariation»</code> trägt, müssen Post-Build- bzw. Pre-Compile-Variationspunkte aufgelöst sein, bevor UCM ein deploybares Artefakt bindet.</li>\n<li><strong>Sicherheitsimplikation:</strong> Durch das Uploaden von <code>CryptoServiceKey</code>, <code>IPSecConfigProps</code> oder <code>FirewallRule</code> müssen strikte Signaturprüfungen und Zugriffsrechte (UCM-Authentifizierung) greifen, um unautorisierte Rekonfigurationen von IDS/Firewall-Subsystemen auf Machine-Ebene zu verhindern.</li>\n</ul>"}, {"id": "FIG-129ae5813a2d9c71", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML Class Diagram), AUTOSAR Adaptive Platform (TPS Manifest Specification, R23-11, Kapitel 15 <em>Package Management</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Vererbungshierarchie für <code>UploadableDesignElement</code>. Es spezifiziert sämtliche modellbasierten Konfigurations- und Design-Artefakte (ARXML), die über das AUTOSAR Adaptive <em>Update and Configuration Management</em> (UCM) als eigenständige Software Packages bzw. Deployable Content auf eine Zielmaschine übertragen, aktualisiert oder gepatcht werden können, ohne die gesamte Systemkonfiguration neu flashen zu müssen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basis-Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadablePackageElement</code></strong> (<code>ARElement</code>, abstrakt): Wurzelklasse für alle paketierbaren Manifest- und Design-Entitäten innerhalb eines Software Packages.</li>\n<li><strong><code>UploadableDesignElement</code></strong> (abstrakt): Direkte Spezialisierung (<code>Generalization</code>) von <code>UploadablePackageElement</code>. Dient als polymorpher Ankerpunkt für alle Entwurfselemente der System-, Netzwerk-, Sicherheits- und Servicearchitektur.</li>\n</ul>\n<p class=\"fig-p\">#### Abgeleitete Spezialisierungen (Subklassen von <code>UploadableDesignElement</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Service-Oriented Communication & Deployment (ara::com / Middleware):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>AdaptivePlatformServiceInstance</code>: Modellierung von serviceorientierten Plattform-Service-Instanzen auf der Adaptive Platform.</li>\n<li><code>ServiceInterfaceDeployment</code>: Protokollspezifische Bindung von Schnittstellen (SOME/IP, DDS, IPC).</li>\n<li><code>ServiceInstanceToPortPrototypeMapping</code>: Zuordnung von Service-Instanzen zu Port-Prototypen einer Softwarekomponente.</li>\n<li><code>ServiceInstanceToMachineMapping</code>: Bindung einer Service-Instanz an eine konkrete Maschine (Netzwerk-Endpunkt).</li>\n<li><code>ServiceInstanceToSignalMapping</code> & <code>SignalServiceTranslationPropsSet</code> (<code>ARElement</code>): Gateway-Mapping zwischen klassischer signalbasierter Kommunikation (CAN/LIN/FlexRay) und serviceorientierten Events/Methoden.</li>\n<li><strong>SOME/IP-Spezifika:</strong></li>\n<li><code>SomeipRemoteUnicastConfig</code>, <code>SomeipRemoteMulticastConfig</code> (<code>ARElement</code>).</li>\n<li><code>SomeipSdClientServiceInstanceConfig</code>, <code>SomeipSdServerServiceInstanceConfig</code> (<code>ARElement</code>): SD-Timing und Instanzkonfiguration.</li>\n<li><code>SomeipSdClientEventGroupTimingConfig</code>, <code>SomeipSdServerEventGroupTimingConfig</code> (<code>ARElement</code>).</li>\n<li><code>SomeipDataPrototypeTransformationProps</code>, <code>TransformationPropsSet</code>, <code>TransformationPropsToServiceInterfaceElementMapping</code>, <code>TlvDataIdDefinitionSet</code> (<code>ARElement</code>): Serialisierungs- und TLV-Encoding-Regeln.</li>\n<li><strong>DDS-Spezifika:</strong> <code>DdsSecureGovernance</code>, <code>DdsTopicAccessRule</code> (Zugriffs- und Sicherheitsrichtlinien für DDS-Topics).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk-, Bus- & Protokoll-Stack (FIBEX / Classic & Adaptive Interop):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CommunicationCluster</code> (<code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>): Repräsentation von Bus-Clustern (Ethernet, CAN, CAN XL) mit Unterstützung für Variantenbildung.</li>\n<li><code>CanXlProps</code> (<code>ARElement</code>): Spezifische Frame- und Bitraten-Parameter für CAN XL.</li>\n<li><code>GenericTpConnection</code>: Generische Transportprotokoll-Verbindung für segmentierte Datenübertragung.</li>\n<li><code>Pdu</code>, <code>ISignal</code>, <code>ISignalGroup</code> (<code>FibexElement</code>): Signal- und PDU-Definitionen für deterministische Buskommunikation.</li>\n<li><code>SocketConnectionIpduIdentifierSet</code> (<code>FibexElement</code>): PDU-zu-Socket-Multiplexing über TCP/UDP.</li>\n<li><code>EthIpProps</code>, <code>EthTcpIpProps</code>, <code>EthTcpIpIcmpProps</code> (<code>ARElement</code>): Parameter für IP/TCP/UDP/ICMP-Stacks (Subnetzmasken, MTU, Window Sizes).</li>\n<li><code>NmConfig</code> (<code>FibexElement</code>): Network Management-Konfiguration (AUTOSAR NM / UDP NM).</li>\n<li><code>GlobalTimeDomain</code> (<code>FibexElement</code>): Synchronisationsdomäne für gPTP / IEEE 802.1AS (ara::tsync).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security, Krypto & Intrusion Detection (ara::crypto, IDS, Firewall):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CryptoServicePrimitive</code>, <code>CryptoServiceKey</code>, <code>CryptoServiceCertificate</code> (<code>ARElement</code>): Spezifikation kryptografischer Primitive, Schlüssel und X.509-Zertifikate.</li>\n<li><code>CryptoKeySlotUserDesign</code>, <code>CryptoKeySlotUserDesignMapping</code>, <code>CryptoKeySlotUsageDesignMapping</code>: Design-Elemente und Mappings zur Zuweisung und Nutzung von kryptografischen Key-Slots durch Applikationen und Plattformdienste.</li>\n<li><code>SecureComProps</code>, <code>IPSecConfigProps</code> (<code>ARElement</code>): Parameter für gesicherte Kommunikationskanäle und IPsec.</li>\n<li><code>MacSecParticipantSet</code>, <code>MacSecGlobalKeyProps</code> (<code>ARElement</code>): MACsec-Teilnehmer und globale Schlüssel auf Verbindungsschicht.</li>\n<li><code>IdsDesign</code>, <code>IdsCommonElement</code> (<code>ARElement</code>), <code>SecurityEventReportToSecurityEventDefinitionMapping</code>: Intrusion Detection System (IDS) Architektur und Event-Mappings.</li>\n<li><code>FirewallRule</code> (<code>ARElement</code>), <code>StateDependentFirewall</code>: Paketfilter und zustandsabhängige Firewall-Konfigurationen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Execution Management, State Management & System-Topologie:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Executable</code> (<code>AtpClassifier</code>): Definition ausführbarer Binärdateien im Software Package.</li>\n<li><code>FunctionGroupSet</code> (<code>AtpClassifier</code>), <code>ModeDeclarationGroup</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Funktionsgruppen und Modus-Deklarationen für State Management.</li>\n<li><code>MachineDesign</code> (<code>AtpStructureElement</code>, <code>FibexElement</code>): Hardware- und Netzwerkarchitektur der Maschine.</li>\n<li><code>System</code> (<code>ARElement</code>, <code>AtpStructureElement</code>): Systemweites Integrationsmodell.</li>\n<li><code>Documentation</code> (<code>ARElement</code>): Dokumentations- und Spezifikationsmetadaten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Logging, Tracing & End-to-End Protection:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DltEcu</code>, <code>DltContext</code> (<code>ARElement</code>), <code>LogAndTraceMessageCollectionSet</code> (<code>ARElement</code>): Konfiguration für Diagnostic Log and Trace (ara::dlt).</li>\n<li><code>E2EProfileConfigurationSet</code>, <code>E2EProfileCompatibilityProps</code> (<code>ARElement</code>): End-to-End-Absicherungsprofile und Kompatibilitätseigenschaften.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches AUTOSAR-Metamodell existiert kein direkter Call-Stack oder sequenzielles Laufzeitverhalten. Die dynamische Relevanz greift im <strong>UCM-Lifecycle</strong>:</p>\n<ol class=\"fig-list\">\n<li><strong>Paket-Ingestion:</strong> UCM (<code>ara::ucm</code>) empfängt ein Software Package (<code>SwPackage</code>), dessen Manifest auf <code>UploadablePackageElement</code> verweist.</li>\n<li><strong>Metamodell-Auflösung:</strong> Der Manifest-Parser validiert die Subklassen von <code>UploadableDesignElement</code> gegen die Schemata der Plattform.</li>\n<li><strong>Inkrementelle Rekonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Werden z. B. <code>FirewallRule</code> oder <code>StateDependentFirewall</code> aktualisiert, triggert der UCM-Aktivierungsschritt eine Neugenerierung bzw. Neuladung der OS-/Kernel-Netfilter-Tabellen.</li>\n<li>Wird ein <code>ServiceInstanceToMachineMapping</code> aktualisiert, rekonfiguriert der ara::com Service-Discovery-Daemon (SOME/IP SD / DDS Discovery) die lokalen Endpunkte zur Laufzeit.</li>\n<li>Änderungen an <code>ModeDeclarationGroup</code> oder <code>FunctionGroupSet</code> synchronisieren die Zustandsübergänge im Execution Management (<code>ara::exec</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>UCM-Granularität & Entkopplung:</strong> Entwickler von Adaptive-Anwendungen müssen Design-Artefakte strikt modular modellieren. Da alle dargestellten Klassen eigenständige <code>UploadableDesignElement</code>-Objekte sind, können Netzwerkmatrizen (FIBEX/Signals), Diagnosekonfigurationen (DLT) und Sicherheitsrichtlinien getrennt von den eigentlichen Executables aktualisiert werden.</li>\n<li><strong>Manifest-Generierung:</strong> Toolchains (Generatoren) kompilieren diese M2-Elemente in spezifische Manifeste:</li>\n<li><code>Executable</code>, <code>FunctionGroupSet</code> $\\rightarrow$ <em>Execution Manifest</em> (<code>.arxml</code> / JSON / BSON).</li>\n<li><code>ServiceInterfaceDeployment</code>, <code>ServiceInstanceToPortPrototypeMapping</code> $\\rightarrow$ <em>Service Instance Manifest</em>.</li>\n<li><code>MachineDesign</code>, <code>EthTcpIpProps</code>, <code>CryptoService<em></code> $\\rightarrow$ </em>Machine Manifest*.</li>\n<li><strong>Variantenmanagement:</strong> Da <code>CommunicationCluster</code> das Stereotyp <code>«atpVariation»</code> trägt, müssen Post-Build- bzw. Pre-Compile-Variationspunkte aufgelöst sein, bevor UCM ein deploybares Artefakt bindet.</li>\n<li><strong>Sicherheitsimplikation:</strong> Durch das Uploaden von <code>CryptoServiceKey</code>, <code>IPSecConfigProps</code> oder <code>FirewallRule</code> müssen strikte Signaturprüfungen und Zugriffsrechte (UCM-Authentifizierung) greifen, um unautorisierte Rekonfigurationen von IDS/Firewall-Subsystemen auf Machine-Ebene zu verhindern.</li>\n</ul>"}, {"id": "FIG-b319b061c3e65dce", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML Class Diagram), AUTOSAR Adaptive Platform (TPS Manifest Specification, R23-11, Kapitel 15 <em>Package Management</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Vererbungshierarchie für <code>UploadableDesignElement</code>. Es spezifiziert sämtliche modellbasierten Konfigurations- und Design-Artefakte (ARXML), die über das AUTOSAR Adaptive <em>Update and Configuration Management</em> (UCM) als eigenständige Software Packages bzw. Deployable Content auf eine Zielmaschine übertragen, aktualisiert oder gepatcht werden können, ohne die gesamte Systemkonfiguration neu flashen zu müssen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basis-Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadablePackageElement</code></strong> (<code>ARElement</code>, abstrakt): Wurzelklasse für alle paketierbaren Manifest- und Design-Entitäten innerhalb eines Software Packages.</li>\n<li><strong><code>UploadableDesignElement</code></strong> (abstrakt): Direkte Spezialisierung (<code>Generalization</code>) von <code>UploadablePackageElement</code>. Dient als polymorpher Ankerpunkt für alle Entwurfselemente der System-, Netzwerk-, Sicherheits- und Servicearchitektur.</li>\n</ul>\n<p class=\"fig-p\">#### Abgeleitete Spezialisierungen (Subklassen von <code>UploadableDesignElement</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>Service-Oriented Communication & Deployment (ara::com / Middleware):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>AdaptivePlatformServiceInstance</code>: Modellierung von serviceorientierten Plattform-Service-Instanzen auf der Adaptive Platform.</li>\n<li><code>ServiceInterfaceDeployment</code>: Protokollspezifische Bindung von Schnittstellen (SOME/IP, DDS, IPC).</li>\n<li><code>ServiceInstanceToPortPrototypeMapping</code>: Zuordnung von Service-Instanzen zu Port-Prototypen einer Softwarekomponente.</li>\n<li><code>ServiceInstanceToMachineMapping</code>: Bindung einer Service-Instanz an eine konkrete Maschine (Netzwerk-Endpunkt).</li>\n<li><code>ServiceInstanceToSignalMapping</code> & <code>SignalServiceTranslationPropsSet</code> (<code>ARElement</code>): Gateway-Mapping zwischen klassischer signalbasierter Kommunikation (CAN/LIN/FlexRay) und serviceorientierten Events/Methoden.</li>\n<li><strong>SOME/IP-Spezifika:</strong></li>\n<li><code>SomeipRemoteUnicastConfig</code>, <code>SomeipRemoteMulticastConfig</code> (<code>ARElement</code>).</li>\n<li><code>SomeipSdClientServiceInstanceConfig</code>, <code>SomeipSdServerServiceInstanceConfig</code> (<code>ARElement</code>): SD-Timing und Instanzkonfiguration.</li>\n<li><code>SomeipSdClientEventGroupTimingConfig</code>, <code>SomeipSdServerEventGroupTimingConfig</code> (<code>ARElement</code>).</li>\n<li><code>SomeipDataPrototypeTransformationProps</code>, <code>TransformationPropsSet</code>, <code>TransformationPropsToServiceInterfaceElementMapping</code>, <code>TlvDataIdDefinitionSet</code> (<code>ARElement</code>): Serialisierungs- und TLV-Encoding-Regeln.</li>\n<li><strong>DDS-Spezifika:</strong> <code>DdsSecureGovernance</code>, <code>DdsTopicAccessRule</code> (Zugriffs- und Sicherheitsrichtlinien für DDS-Topics).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk-, Bus- & Protokoll-Stack (FIBEX / Classic & Adaptive Interop):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CommunicationCluster</code> (<code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>): Repräsentation von Bus-Clustern (Ethernet, CAN, CAN XL) mit Unterstützung für Variantenbildung.</li>\n<li><code>CanXlProps</code> (<code>ARElement</code>): Spezifische Frame- und Bitraten-Parameter für CAN XL.</li>\n<li><code>GenericTpConnection</code>: Generische Transportprotokoll-Verbindung für segmentierte Datenübertragung.</li>\n<li><code>Pdu</code>, <code>ISignal</code>, <code>ISignalGroup</code> (<code>FibexElement</code>): Signal- und PDU-Definitionen für deterministische Buskommunikation.</li>\n<li><code>SocketConnectionIpduIdentifierSet</code> (<code>FibexElement</code>): PDU-zu-Socket-Multiplexing über TCP/UDP.</li>\n<li><code>EthIpProps</code>, <code>EthTcpIpProps</code>, <code>EthTcpIpIcmpProps</code> (<code>ARElement</code>): Parameter für IP/TCP/UDP/ICMP-Stacks (Subnetzmasken, MTU, Window Sizes).</li>\n<li><code>NmConfig</code> (<code>FibexElement</code>): Network Management-Konfiguration (AUTOSAR NM / UDP NM).</li>\n<li><code>GlobalTimeDomain</code> (<code>FibexElement</code>): Synchronisationsdomäne für gPTP / IEEE 802.1AS (ara::tsync).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security, Krypto & Intrusion Detection (ara::crypto, IDS, Firewall):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CryptoServicePrimitive</code>, <code>CryptoServiceKey</code>, <code>CryptoServiceCertificate</code> (<code>ARElement</code>): Spezifikation kryptografischer Primitive, Schlüssel und X.509-Zertifikate.</li>\n<li><code>CryptoKeySlotUserDesign</code>, <code>CryptoKeySlotUserDesignMapping</code>, <code>CryptoKeySlotUsageDesignMapping</code>: Design-Elemente und Mappings zur Zuweisung und Nutzung von kryptografischen Key-Slots durch Applikationen und Plattformdienste.</li>\n<li><code>SecureComProps</code>, <code>IPSecConfigProps</code> (<code>ARElement</code>): Parameter für gesicherte Kommunikationskanäle und IPsec.</li>\n<li><code>MacSecParticipantSet</code>, <code>MacSecGlobalKeyProps</code> (<code>ARElement</code>): MACsec-Teilnehmer und globale Schlüssel auf Verbindungsschicht.</li>\n<li><code>IdsDesign</code>, <code>IdsCommonElement</code> (<code>ARElement</code>), <code>SecurityEventReportToSecurityEventDefinitionMapping</code>: Intrusion Detection System (IDS) Architektur und Event-Mappings.</li>\n<li><code>FirewallRule</code> (<code>ARElement</code>), <code>StateDependentFirewall</code>: Paketfilter und zustandsabhängige Firewall-Konfigurationen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Execution Management, State Management & System-Topologie:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Executable</code> (<code>AtpClassifier</code>): Definition ausführbarer Binärdateien im Software Package.</li>\n<li><code>FunctionGroupSet</code> (<code>AtpClassifier</code>), <code>ModeDeclarationGroup</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Funktionsgruppen und Modus-Deklarationen für State Management.</li>\n<li><code>MachineDesign</code> (<code>AtpStructureElement</code>, <code>FibexElement</code>): Hardware- und Netzwerkarchitektur der Maschine.</li>\n<li><code>System</code> (<code>ARElement</code>, <code>AtpStructureElement</code>): Systemweites Integrationsmodell.</li>\n<li><code>Documentation</code> (<code>ARElement</code>): Dokumentations- und Spezifikationsmetadaten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Logging, Tracing & End-to-End Protection:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DltEcu</code>, <code>DltContext</code> (<code>ARElement</code>), <code>LogAndTraceMessageCollectionSet</code> (<code>ARElement</code>): Konfiguration für Diagnostic Log and Trace (ara::dlt).</li>\n<li><code>E2EProfileConfigurationSet</code>, <code>E2EProfileCompatibilityProps</code> (<code>ARElement</code>): End-to-End-Absicherungsprofile und Kompatibilitätseigenschaften.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches AUTOSAR-Metamodell existiert kein direkter Call-Stack oder sequenzielles Laufzeitverhalten. Die dynamische Relevanz greift im <strong>UCM-Lifecycle</strong>:</p>\n<ol class=\"fig-list\">\n<li><strong>Paket-Ingestion:</strong> UCM (<code>ara::ucm</code>) empfängt ein Software Package (<code>SwPackage</code>), dessen Manifest auf <code>UploadablePackageElement</code> verweist.</li>\n<li><strong>Metamodell-Auflösung:</strong> Der Manifest-Parser validiert die Subklassen von <code>UploadableDesignElement</code> gegen die Schemata der Plattform.</li>\n<li><strong>Inkrementelle Rekonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Werden z. B. <code>FirewallRule</code> oder <code>StateDependentFirewall</code> aktualisiert, triggert der UCM-Aktivierungsschritt eine Neugenerierung bzw. Neuladung der OS-/Kernel-Netfilter-Tabellen.</li>\n<li>Wird ein <code>ServiceInstanceToMachineMapping</code> aktualisiert, rekonfiguriert der ara::com Service-Discovery-Daemon (SOME/IP SD / DDS Discovery) die lokalen Endpunkte zur Laufzeit.</li>\n<li>Änderungen an <code>ModeDeclarationGroup</code> oder <code>FunctionGroupSet</code> synchronisieren die Zustandsübergänge im Execution Management (<code>ara::exec</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>UCM-Granularität & Entkopplung:</strong> Entwickler von Adaptive-Anwendungen müssen Design-Artefakte strikt modular modellieren. Da alle dargestellten Klassen eigenständige <code>UploadableDesignElement</code>-Objekte sind, können Netzwerkmatrizen (FIBEX/Signals), Diagnosekonfigurationen (DLT) und Sicherheitsrichtlinien getrennt von den eigentlichen Executables aktualisiert werden.</li>\n<li><strong>Manifest-Generierung:</strong> Toolchains (Generatoren) kompilieren diese M2-Elemente in spezifische Manifeste:</li>\n<li><code>Executable</code>, <code>FunctionGroupSet</code> $\\rightarrow$ <em>Execution Manifest</em> (<code>.arxml</code> / JSON / BSON).</li>\n<li><code>ServiceInterfaceDeployment</code>, <code>ServiceInstanceToPortPrototypeMapping</code> $\\rightarrow$ <em>Service Instance Manifest</em>.</li>\n<li><code>MachineDesign</code>, <code>EthTcpIpProps</code>, <code>CryptoService<em></code> $\\rightarrow$ </em>Machine Manifest*.</li>\n<li><strong>Variantenmanagement:</strong> Da <code>CommunicationCluster</code> das Stereotyp <code>«atpVariation»</code> trägt, müssen Post-Build- bzw. Pre-Compile-Variationspunkte aufgelöst sein, bevor UCM ein deploybares Artefakt bindet.</li>\n<li><strong>Sicherheitsimplikation:</strong> Durch das Uploaden von <code>CryptoServiceKey</code>, <code>IPSecConfigProps</code> oder <code>FirewallRule</code> müssen strikte Signaturprüfungen und Zugriffsrechte (UCM-Authentifizierung) greifen, um unautorisierte Rekonfigurationen von IDS/Firewall-Subsystemen auf Machine-Ebene zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-3badaa1e7ed83a48", "to": "FIG-129ae5813a2d9c71", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>AdaptivePlatformServiceInstance</code>: Als Subklasse von <code>UploadableDesignElement</code> explizit modelliert (korrigiert die zuvor leere Box unterhalb von <code>ServiceInstanceToMachineMapping</code>).</li>\n<li><code>GenericTpConnection</code>: Neu als Subklasse von <code>UploadableDesignElement</code> hinzugefügt.</li>\n<li><code>CryptoKeySlotUserDesign</code>: Neu als Subklasse von <code>UploadableDesignElement</code> hinzugefügt.</li>\n<li><code>CryptoKeySlotUserDesignMapping</code>: Neu als Subklasse von <code>UploadableDesignElement</code> hinzugefügt.</li>\n<li><code>CryptoKeySlotUsageDesignMapping</code>: Neu als Subklasse von <code>UploadableDesignElement</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-129ae5813a2d9c71", "to": "FIG-b319b061c3e65dce", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
